  Definition dr_frame (m : mem) (spv : Z) (j0 : list byte) (ca cs s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra : word) : Prop :=
    rw_cells bsegs m spv [CB 8 j0; C8 ca; C8 cs; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

