    (* [comment removed for export] *)
    Definition dr_entry_post (m : mem) (T : list qbatch) (t0 t1 t2 a4 a5 a6 a7 t3 t4 t5 t6 : word) : machine_state -> Prop :=
      fun ms' => exists (a1' : word) (j0 : list byte) m',
        ms' = (match T with
               | [] => MS (mkR (wz 0x5209c) (Z_to_bv 64 T0) gp tp t0 t1 t2 s0 s1 (wz 0) a1' ca cs a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F (Z_to_bv 64 0x5209c) fc None m' (seg_rom bsegs)
               | _ => dr_head_ms (wz 0x5209c) t0 t1 t2 a1' ca cs a4 a5 a6 a7 s4 s6 s7 s8 s9 t3 t4 t5 t6 T 0x5230c m'
               end)
        /\ munch [(spv, T0)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
        /\ rw_cells bsegs m' T0 [C8 (wz (zlen T)); C8 (wz (hd 0 (map qb_addr T))); C8 (wz (last (map qb_addr T) 0)); C8 (wz (bsum T))]
        /\ bseg m' T 0
        /\ match T with [] => stk bsegs m' lo T0 | _ => stk bsegs m' lo spv /\ FRAME m' j0 end.
